def eval_expr(expr):
    import re
    tokens = re.findall(r'\d+|[+\-*/()]', expr.replace(' ', ''))
    def parse(tokens):
        def helper(it):
            num_stack = []
            op_stack = []
            def apply_op():
                b = num_stack.pop()
                a = num_stack.pop()
                op = op_stack.pop()
                if op == '+':
                    num_stack.append(a + b)
                elif op == '-':
                    num_stack.append(a - b)
                elif op == '*':
                    num_stack.append(a * b)
                elif op == '/':
                    if b == 0:
                        raise ValueError('division by zero')
                    num_stack.append(a // b)
            precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
            while True:
                try:
                    token = next(it)
                except StopIteration:
                    break
                if token.isdigit():
                    num_stack.append(int(token))
                elif token == '(':
                    num_stack.append(helper(it))
                elif token == ')':
                    break
                else:  # operator
                    while (op_stack and op_stack[-1] != '(' and
                           precedence[op_stack[-1]] >= precedence[token]):
                        apply_op()
                    op_stack.append(token)
            while op_stack:
                apply_op()
            return num_stack[0]
        return helper(iter(tokens))
    return parse(tokens)
