def evaluate(expr):
    def precedence(op):
        return {'+':1, '-':1, '*':2, '/':2}.get(op, 0)
    def apply_op(a, b, op):
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            return a // b
    nums = []
    ops = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            val = 0
            while i < len(expr) and expr[i].isdigit():
                val = val * 10 + int(expr[i])
                i += 1
            nums.append(val)
            continue
        if expr[i] == '(':
            ops.append(expr[i])
        elif expr[i] == ')':
            while ops and ops[-1] != '(':
                b, a = nums.pop(), nums.pop()
                nums.append(apply_op(a, b, ops.pop()))
            ops.pop()  # remove '('
        else:  # operator
            while ops and precedence(ops[-1]) >= precedence(expr[i]):
                b, a = nums.pop(), nums.pop()
                nums.append(apply_op(a, b, ops.pop()))
            ops.append(expr[i])
        i += 1
    while ops:
        b, a = nums.pop(), nums.pop()
        nums.append(apply_op(a, b, ops.pop()))
    return nums[0]
