def kth_smallest_bst(tree, k):
    # In‑order traversal generator
    def inorder(node):
        if node is None:
            return
        val, left, right = node
        yield from inorder(left)
        yield val
        yield from inorder(right)
    gen = inorder(tree)
    for _ in range(k - 1):
        next(gen)
    return next(gen)
