def parse_csv_line(line):
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1
            start = i
            field = ''
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        field += '"'
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    field += line[i]
                    i += 1
            fields.append(field)
            # Skip optional comma
            if i < n and line[i] == ',':
                i += 1
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
    return fields
